    end = datetime.date.fromisoformat(params['end'])

    if start > end:
        return {'days': 0}

    count = 0
    current = start
    while current <= end:
        if current.weekday() < 5:  # Monday (0) through Friday (4)
            count += 1
        current += datetime.timedelta(days=1)

    return {'days': count}

